function writeStore(store) {
  ensureDataMigrated()
  const file = storeFile()
  ensureDirs()
  const tmp = file + '.' + process.pid + '.tmp'
  writeFileSync(tmp, JSON.stringify(store, null, 2) + '\n', 'utf8')
