      "path": "lib/client.js",
      "content": "/**\n * 插件名片 · 浏览器半边（v0.2）\n *\n * 页签：\n *  - 备注管理：按文件夹/收藏分组，组合包可折叠子行；右侧编辑图标/说明/备注\n *  - 插件管理：列表 / 铺陈两种视图，文件夹、收藏、拖拽排序、启用开关\n * 详情页：保留「名片」区块\n */\nwindow.__ModuleLoader__.load({\n  id: \"dsh-plugin-namecards\",\n  factory: (require) => {\n    const react = require(\"react\")\n    const { useCallback, useEffect, useMemo, useRef, useState } = react\n    const { jsx, jsxs } = require(\"react/jsx-runtime\")\n\n    const name = \"dsh-plugin-namecards\"\n    const inject = [\"slots\"]\n    const BASE = \"/dsh-plugin-namecards\"\n    const MAX_DESC = 300\n    const MAX_NOTE = 60\n    const COLLATOR = new Intl.Collator(\"zh-Hans-CN\", { numeric: true, sensitivity: \"base\" })\n\n    /* ---------------- 工具 ---------------- */\n\n    function iconUrl(token) {\n      if (typeof token !== \"string\") return undefined\n      if (token.indexOf(\"builtin:\") === 0) return BASE + \"/icon/builtin/\" + token.slice(8) + \".svg\"\n      if (token.indexOf(\"file:\") === 0) return BASE + \"/icon/file/\" + token.slice(5)\n      return undefined\n    }\n\n    function rowKey(bundleName, rowId) { return bundleName + \"#\" + rowId }\n\n    function resolveText(value) {\n      if (typeof value === \"string\") return value\n      if (value === null || typeof value !== \"object\") return undefined\n      const lang = String((document.documentElement && document.documentElement.lang) || navigator.language || \"zh\").toLowerCase()\n      if (typeof value[lang] === \"string\") return value[lang]\n      if (lang.indexOf(\"zh\") === 0 && typeof value.zh === \"string\") return value.zh\n      if (typeof value.en === \"string\") return value.en\n      const values = Object.keys(value).map((k) => value[k]).filter((v) => typeof v === \"string\")\n      return values.length > 0 ? values[0] : undefined\n    }\n\n    function isHan(text) { return /[\\u3400-\\u9fff]/.test(String(text || \"\")) }\n\n    async function apiGet(path) {\n      const response = await fetch(BASE + path, { headers: { Accept: \"application/json\" }, credentials: \"same-origin\" })\n      if (!response.ok) throw new Error(\"HTTP \" + response.status)\n      return response.json()\n    }\n\n    async function apiPost(path, body) {\n      const response = await fetch(BASE + path, {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"application/json\", Accept: \"application/json\" },\n        credentials: \"same-origin\",\n        body: JSON.stringify(body)\n      })\n      const data = await response.json().catch(() => ({}))\n      if (!response.ok || data.ok === false) throw new Error(data.error || (\"HTTP \" + response.status))\n      return data\n    }\n\n    /* @dsh-plugin-namecards-css-start */\n    const CSS_TEXT = \".dpc-root{display:flex;flex-direction:column;gap:14px;color:var(--dsw-alias-label-primary,#e9ecf2);font-size:13px;line-height:20px;max-width:100%}\\n.dpc-bar{display:flex;flex-wrap:wrap;align-items:center;gap:10px}\\n.dpc-spacer{flex:1}\\n.dpc-hint{color:var(--dsw-alias-label-tertiary,#8e96a5);font-size:12px;line-height:18px}\\n.dpc-btn{display:inline-flex;align-items:center;justify-content:center;gap:6px;height:30px;padding:0 12px;border-radius:8px;border:1px solid var(--dsw-alias-border-l3,#2a2f3a);background:transparent;color:inherit;font:inherit;cursor:pointer;text-decoration:none;box-sizing:border-box}\\n.dpc-btn:hover{background:var(--dsw-alias-interactive-bg-hover,#1f242e)}\\n.dpc-btn[disabled]{opacity:.5;cursor:default}\\n.dpc-btn--primary{background:var(--dsw-alias-state-business-primary,#5b8cff);border-color:transparent;color:#0b1220;font-weight:600}\\n.dpc-btn--danger{color:#f27373}\\n.dpc-input,.dpc-textarea{box-sizing:border-box;width:100%;border:1px solid var(--dsw-alias-border-l3,#2a2f3a);border-radius:9px;background:var(--dsw-alias-bg-l1,#14171d);color:inherit;font:inherit;padding:8px 10px;resize:vertical}\\n.dpc-input:focus,.dpc-textarea:focus{outline:2px solid var(--dsw-alias-state-business-primary,#5b8cff);outline-offset:-1px;border-color:transparent}\\n.dpc-search{width:260px;height:30px;padding:4px 10px}\\n.dpc-seg{display:inline-flex;border:1px solid var(--dsw-alias-border-l3,#2a2f3a);border-radius:8px;padding:2px;gap:2px;background:#141821}\\n.dpc-segbtn{border:0;background:transparent;color:var(--dsw-alias-label-tertiary,#8e96a5);font:inherit;font-size:11.5px;padding:3px 12px;border-radius:6px;cursor:pointer}\\n.dpc-segbtn.is-on{background:#2A3140;color:var(--dsw-alias-label-primary,#e9ecf2);font-weight:600}\\n.dpc-caret{border:0;background:transparent;color:var(--dsw-alias-label-tertiary,#8e96a5);cursor:pointer;font-size:11px;padding:2px 4px;line-height:1}\\n.dpc-caret--inline{margin-right:2px}\\n.dpc-ctitle{font-size:12.5px;font-weight:600;color:var(--dsw-alias-label-primary,#e9ecf2)}\\n.dpc-ccount{font-size:11px;color:var(--dsw-alias-label-tertiary,#8e96a5)}\\n.dpc-ricon{width:18px;height:18px;flex:none;display:flex;align-items:center;justify-content:center}\\n/* editor */\\n.dpc-editor{display:flex;flex-direction:column;gap:12px}\\n.dpc-editor--compact{gap:10px}\\n.dpc-preview{display:flex;align-items:center;gap:12px;padding:10px;border:1px dashed var(--dsw-alias-border-l3,#2a2f3a);border-radius:10px;background:#14171d}\\n.dpc-preview img{border-radius:10px;object-fit:contain}\\n.dpc-preview .dpc-ph{width:44px;height:44px;border-radius:10px;flex:none;background:#222833;display:flex;align-items:center;justify-content:center;color:#9aa3b2}\\n.dpc-preview-main{min-width:0;flex:1}\\n.dpc-preview-title{font-weight:600;font-size:13px}\\n.dpc-preview-desc{color:var(--dsw-alias-label-secondary,#8e96a5);font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\\n.dpc-field{display:flex;flex-direction:column;gap:6px}\\n.dpc-label{display:flex;align-items:center;gap:8px;font-weight:600;font-size:12px;flex-wrap:wrap}\\n.dpc-label .dpc-hint{margin-left:auto;font-weight:400}\\n.dpc-count{font-size:11px;color:var(--dsw-alias-label-tertiary,#8e96a5);text-align:right}\\n.dpc-icons{display:flex;flex-wrap:wrap;gap:8px;align-items:center}\\n.dpc-icon{width:38px;height:38px;padding:0;border-radius:9px;border:2px solid transparent;background:transparent;cursor:pointer;overflow:hidden;flex:none}\\n.dpc-icon img{width:100%;height:100%;display:block;border-radius:7px}\\n.dpc-icon.is-on{border-color:var(--dsw-alias-state-business-primary,#5b8cff)}\\n.dpc-icon--upload{display:flex;align-items:center;justify-content:center;border:1px dashed var(--dsw-alias-border-l3,#2a2f3a);color:var(--dsw-alias-label-tertiary,#8e96a5);font-size:17px}\\n.dpc-switch{display:inline-flex;align-items:center;gap:8px;cursor:pointer;user-select:none;font-size:12px}\\n.dpc-switch input{accent-color:var(--dsw-alias-state-business-primary,#5b8cff);width:15px;height:15px}\\n.dpc-actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap}\\n.dpc-toast{padding:6px 10px;border-radius:8px;background:#1f2a3d;color:#bcd2ff;font-size:12px;align-self:flex-start}\\n.dpc-toast--floating{position:fixed;left:50%;bottom:28px;transform:translateX(-50%);z-index:90;box-shadow:0 6px 24px rgba(0,0,0,.35)}\\n/* manager list */\\n.dpc-manager-list{display:flex;flex-direction:column;gap:10px;padding-bottom:40px}\\n.dpc-mcontainer{border:1px solid var(--dsw-alias-border-l3,#2a2f3a);border-radius:12px;background:#12151c;overflow:hidden}\\n.dpc-mchead{display:flex;align-items:center;gap:8px;padding:8px 12px;background:#14171d;border-bottom:1px solid var(--dsw-alias-border-l3,#2a2f3a)}\\n.dpc-mitems{display:flex;flex-direction:column;gap:2px;padding:6px}\\n.dpc-mbundle{border-radius:8px}\\n.dpc-mbundle.is-drag,.dpc-icon-cell.is-drag{opacity:.5}\\n.dpc-mrow{display:flex;align-items:center;gap:10px;padding:8px 10px;border-radius:8px;background:var(--dsw-alias-bg-l1,#171a21);cursor:pointer}\\n.dpc-mrow:hover{background:var(--dsw-alias-interactive-bg-hover,#1f242e)}\\n.dpc-mrow--sub{background:transparent;padding:4px 10px;font-size:12px}\\n.dpc-mrow--sub:hover{background:#1b1f27}\\n.dpc-drag{color:va